import requests
import json
import sys

SESSION = "bddbe9abb3e94d15b52e51143120ebee"
BASE = "http://are-sidecar:8000/mcp"
HEADERS = {
    "Content-Type": "application/json",
    "Accept": "application/json, text/event-stream",
    "Mcp-Session-Id": SESSION
}

def call(method, params=None, request_id=None):
    if request_id is None:
        import random
        request_id = random.randint(1000, 9999)
    payload = {"jsonrpc": "2.0", "method": method, "id": request_id}
    if params is not None:
        payload["params"] = params
    resp = requests.post(BASE, headers=HEADERS, json=payload)
    # Parse SSE response
    text = resp.text
    if "data: " in text:
        for line in text.split("\n"):
            if line.startswith("data: "):
                data = json.loads(line[6:])
                if "result" in data:
                    return data["result"]
                elif "error" in data:
                    return {"error": data["error"]}
    return {"raw": text}

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: mcp_client.py <method> [json_params]")
        sys.exit(1)
    method = sys.argv[1]
    params = {}
    if len(sys.argv) > 2:
        params = json.loads(sys.argv[2])
    result = call(method, params)
    print(json.dumps(result, indent=2))
